Sql:
SELECT c.ClientID, c.LastName & ", " & c.FirstName AS ClientName, cb.FiscalYear, cb.AnnualBudget, GetBudgetUtilizationPct([c].[ClientID],[cb].[FiscalYear]) AS UtilizationPct
FROM tblClients AS c INNER JOIN tblClientBudgets AS cb ON c.ClientID = cb.ClientID
ORDER BY cb.FiscalYear DESC , c.LastName;
